CREATE TABLE IF NOT EXISTS security_storage_counts (name TEXT PRIMARY KEY, rows INTEGER NOT NULL CHECK(rows>=0));
INSERT OR IGNORE INTO security_storage_counts(name,rows) SELECT 'inbox',COUNT(*) FROM inbox;
DROP TRIGGER IF EXISTS security_cap_inbox;
CREATE TRIGGER security_cap_inbox BEFORE INSERT ON inbox WHEN NOT EXISTS(SELECT 1 FROM inbox WHERE update_id=NEW.update_id) AND (SELECT rows FROM security_storage_counts WHERE name='inbox')>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;
CREATE TRIGGER security_count_add_inbox AFTER INSERT ON inbox BEGIN UPDATE security_storage_counts SET rows=rows+1 WHERE name='inbox'; END;
CREATE TRIGGER security_count_remove_inbox AFTER DELETE ON inbox BEGIN UPDATE security_storage_counts SET rows=rows-1 WHERE name='inbox'; END;
INSERT OR IGNORE INTO security_storage_counts(name,rows) SELECT 'jobs',COUNT(*) FROM jobs;
DROP TRIGGER IF EXISTS security_cap_jobs;
CREATE TRIGGER security_cap_jobs BEFORE INSERT ON jobs WHEN NOT EXISTS(SELECT 1 FROM jobs WHERE id=NEW.id) AND (SELECT rows FROM security_storage_counts WHERE name='jobs')>=100000 BEGIN SELECT RAISE(ABORT,'technical storage limit reached'); END;
CREATE TRIGGER security_count_add_jobs AFTER INSERT ON jobs BEGIN UPDATE security_storage_counts SET rows=rows+1 WHERE name='jobs'; END;
CREATE TRIGGER security_count_remove_jobs AFTER DELETE ON jobs BEGIN UPDATE security_storage_counts SET rows=rows-1 WHERE name='jobs'; END;
