CREATE INDEX IF NOT EXISTS inbox_user_pending ON inbox(user_id,status);
CREATE INDEX IF NOT EXISTS jobs_user_pending ON jobs(user_id,status,kind);
CREATE TABLE job_revision_sequence (id INTEGER PRIMARY KEY CHECK(id=1), value INTEGER NOT NULL);
INSERT INTO job_revision_sequence(id,value) SELECT 1,COALESCE(MAX(revision),0) FROM jobs;
CREATE TRIGGER security_interactive_reopen BEFORE UPDATE OF status ON jobs WHEN OLD.status!='pending' AND NEW.status='pending' AND NEW.kind IN ('reply','callback','commands') AND ((SELECT COUNT(*) FROM jobs WHERE status='pending' AND kind IN ('reply','callback','commands'))>=500 OR (SELECT COUNT(*) FROM jobs WHERE user_id=NEW.user_id AND status='pending' AND kind IN ('reply','callback','commands'))>=5) BEGIN SELECT RAISE(ABORT,'interactive queue limit reached'); END;
CREATE TRIGGER security_revision_observe AFTER UPDATE OF revision ON jobs WHEN NEW.revision>(SELECT value FROM job_revision_sequence WHERE id=1) BEGIN UPDATE job_revision_sequence SET value=NEW.revision WHERE id=1; END;
